    "competencia": "II - Elaborar diagnóstico da poligonal de novos parcelamentos e de núcleos urbanos informais a serem regularizados, considerando os seguintes itens: Avaliar as condições de infraestrutura e equipamentos urbanos existentes; Avaliar os projetos de infraestrutura eventualmente existentes, discriminando os responsáveis e os cronogramas de implantação; Identificar as áreas de preservação ambiental e demais áreas de interesse ambiental, possíveis áreas de risco e de inundações, encaminhando-as aos órgãos municipais responsáveis pelo meio ambiente e Defesa Civil para elaboração de estudo técnico, com avaliação da possibilidade e condições para a consolidação da ocupação existente e da necessidade de remoção de moradias, se for o caso; Identificar a necessidade de adequação dos logradouros, espaços livres, áreas destinadas a edifícios públicos e outros equipamentos urbanos demandando-os às secretarias e departamentos afins, devendo a análise do sistema viário ser procedida pelo órgão municipal de trânsito;",
    "sistemaAtende": true,
    "comoAtende": "Consultando dados urbanos e territoriais como: áreas verdes, camadas de APP, Logradouros, cursos d'água, áreas de risco e etc.",
